  { table: 15, x: 92.3, y: 71.3, seats: 6 },
  { table: 16, x: 92.6, y: 88.0, seats: 4 },

  { table: 17, x: 8.0,  y: 53.0, seats: 6 },
  { table: 18, x: 8.0,  y: 73.0, seats: 6 }
