  async function loadAdminNextEvent() {
    setAdminNextEventLoading(true);
    try {
      // Wichtig: Auch der Demo-Admin muss exakt dieselben aktuellen
      // Veranstaltungs-/Reservierungsdaten sehen wie der normale Admin.
      // Der read-only RPC liest per SECURITY DEFINER aus den Live-Daten;
      // Schreibaktionen bleiben weiterhin im Trainings-Proxy.
      const { data, error } = await adminDb.rpc("admin_get_next_event_summary");

      if (error || !data?.length) {
        if (error) console.warn("Nächste Veranstaltung konnte nicht geladen werden:", error.message);
        setAdminNextEvent(null);
        return;
      }

      const event = data[0];
      setAdminNextEvent({
        id: event.event_id,
        title: event.title,
        starts_at: event.starts_at,
        location: event.location,
        reservedSeats: Number(event.reserved_seats || 0),
        totalSeats: Number(event.total_seats || 0)
      });
    } catch (error) {
      console.warn("Nächste Veranstaltung konnte nicht geladen werden:", error);
      setAdminNextEvent(null);
    } finally {
      setAdminNextEventLoading(false);
    }
  }

