  async function reviewAvatar(userId, action) {
    if (readOnly || !userId || avatarReviewBusy[userId]) return;
    setAvatarReviewBusy(prev => ({ ...prev, [userId]: true }));
    try {
      const target = pendingAvatars.find(item => item.id === userId);
      const pendingPath = target?.avatar_pending_url || "";

      const { error } = await adminDb.rpc("admin_review_avatar", {
        p_target_user_id: userId,
        p_action: action
      });
      if (error) throw error;

      if (action === "reject" && pendingPath) {
        const cleanup = await adminDb.storage.from("avatars").remove([pendingPath]);
        if (cleanup.error) console.warn("Abgelehntes Profilfoto konnte nicht aus dem Speicher entfernt werden:", cleanup.error.message);
      }

      setPendingAvatars(prev => prev.filter(item => item.id !== userId));
      alert(action === "approve" ? "Profilfoto freigegeben. ✅" : "Profilfoto abgelehnt. ❌");
    } catch (error) {
      console.error("Profilfoto konnte nicht geprüft werden:", error);
      alert("Das Profilfoto konnte nicht geprüft werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setAvatarReviewBusy(prev => { const next = { ...prev }; delete next[userId]; return next; });
    }
  }

  async function loadAdminFoundDancePairs() {
    setAdminFoundDancePairsLoading(true);

    try {
      const { data: pairs, error: pairError } = await adminDb
        .from("workshop_pairs")
        .select("workshop_id,user1_id,user2_id,created_at")
        .order("created_at", { ascending: false });

      if (pairError) {
        console.error("Fehler beim Laden der gefundenen Tanzpaare:", pairError);
        setAdminFoundDancePairs([]);
        return;
      }

      const rows = pairs || [];
      const workshopIds = [...new Set(rows.map(row => row.workshop_id).filter(Boolean))];
      const userIds = [...new Set(rows.flatMap(row => [row.user1_id, row.user2_id]).filter(Boolean))];

      const [{ data: workshopsData, error: workshopsError }, { data: profilesData, error: profilesError }] = await Promise.all([
        workshopIds.length
          ? adminDb.from("workshops").select("id,title,starts_at,start_time,duration_minutes,workshop_type").in("id", workshopIds)
          : Promise.resolve({ data: [], error: null }),
        userIds.length
          ? adminDb.from("profiles").select("id,display_name").in("id", userIds)
          : Promise.resolve({ data: [], error: null })
      ]);

      if (workshopsError) console.warn("Workshops der Tanzpaare konnten nicht geladen werden:", workshopsError.message);
      if (profilesError) console.warn("Profile der Tanzpaare konnten nicht geladen werden:", profilesError.message);

      const workshopMap = Object.fromEntries((workshopsData || []).map(w => [w.id, w]));
      const profileMap = Object.fromEntries((profilesData || []).map(p => [p.id, p]));

      setAdminFoundDancePairs(rows.map(pair => ({
        ...pair,
        user1_name: profileMap[pair.user1_id]?.display_name || "Unbekannt",
        user2_name: profileMap[pair.user2_id]?.display_name || "Unbekannt",
        workshop: workshopMap[pair.workshop_id] || null
      })));
    } catch (error) {
      console.error("Fehler beim Laden der gefundenen Tanzpaare:", error);
      setAdminFoundDancePairs([]);
    } finally {
      setAdminFoundDancePairsLoading(false);
    }
  }

  async function loadAdminSelfFoundPairs() {
    setAdminSelfFoundPairsLoading(true);
    try {
      // Vermittlungen sollen alle tatsächlich gespeicherten registrierten
      // workshop_pairs anzeigen – auch wenn die Tanzpartnersuche des Workshops
      // inzwischen deaktiviert wurde. Das ist wichtig für bereits bestehende
      // Paare wie Petra ↔ Steffen im Tanzkreis. Die Deaktivierung verhindert
      // weiterhin neue Partnersuchen; sie löscht bzw. versteckt kein bestehendes Paar.
      const [
        { data: requests, error: requestError },
        { data: pairRows, error: pairError }
      ] = await Promise.all([
        adminDb
          .from("contact_requests")
          .select("id,workshop_id,requester_id,recipient_id,created_at")
          .eq("status", "accepted")
          .not("workshop_id", "is", null)
          .order("created_at", { ascending: false }),
        adminDb
          .from("workshop_pairs")
          .select("workshop_id,user1_id,user2_id,created_at")
          .order("created_at", { ascending: false })
      ]);

      if (requestError) throw requestError;
      if (pairError) throw pairError;

      const validRequests = (requests || []).filter(row =>
        row.requester_id && row.recipient_id &&
        row.requester_id !== ADMIN_USER_ID && row.recipient_id !== ADMIN_USER_ID
      );
      const validPairs = (pairRows || []).filter(row =>
        row.user1_id && row.user2_id &&
        row.user1_id !== ADMIN_USER_ID && row.user2_id !== ADMIN_USER_ID
      );

      const workshopIds = [...new Set([
        ...validRequests.map(r => r.workshop_id),
        ...validPairs.map(p => p.workshop_id)
      ].filter(Boolean))];
      const userIds = [...new Set([
        ...validRequests.flatMap(r => [r.requester_id, r.recipient_id]),
        ...validPairs.flatMap(p => [p.user1_id, p.user2_id])
      ].filter(Boolean))];

      const [{ data: workshopRows, error: workshopError }, { data: profileRows, error: profileError }, { data: registrationRows, error: registrationError }] = await Promise.all([
        workshopIds.length
          ? adminDb.from("workshops").select("id,title,starts_at,start_time,duration_minutes,workshop_type").in("id", workshopIds)
          : Promise.resolve({ data: [], error: null }),
        userIds.length
          ? adminDb.from("profiles").select("id,display_name").in("id", userIds)
          : Promise.resolve({ data: [], error: null }),
        workshopIds.length
          ? adminDb.from("workshop_registrations").select("id,workshop_id,user1_id,user2_id,user1_name,user2_name,user1_email,user2_email").in("workshop_id", workshopIds)
          : Promise.resolve({ data: [], error: null })
      ]);

      if (workshopError) throw workshopError;
      if (profileError) throw profileError;
      if (registrationError) throw registrationError;

      const workshopMap = Object.fromEntries((workshopRows || []).map(w => [w.id, w]));
      const profileMap = Object.fromEntries((profileRows || []).map(p => [p.id, p.display_name || "Unbekannt"]));
      const pairSet = new Set(validPairs.map(p => {
        const ids = [p.user1_id, p.user2_id].map(String).sort();
        return `${p.workshop_id}:${ids.join(":")}`;
      }));
      const registrationSet = new Set((registrationRows || []).map(r => {
        const ids = [r.user1_id, r.user2_id].filter(Boolean).map(String).sort();
        return ids.length === 2 ? `${r.workshop_id}:${ids.join(":")}` : null;
      }).filter(Boolean));

      const combined = [];
      const seen = new Set();

      // Zuerst die tatsächlich gespeicherten workshop_pairs. Damit erscheinen
      // auch Paare, deren Workshop später auf „keine Tanzpartnersuche“ gestellt wurde.
      validPairs.forEach(row => {
        const ids = [row.user1_id, row.user2_id].map(String).sort();
        const key = `${row.workshop_id}:${ids.join(":")}`;
        if (seen.has(key)) return;
        seen.add(key);
        combined.push({
          id: `pair-${row.workshop_id}-${ids.join("-")}`,
          pair_id: null,
          workshop_id: row.workshop_id,
          workshop: workshopMap[row.workshop_id] || null,
          user1_id: row.user1_id,
          user2_id: row.user2_id,
          user1_name: profileMap[row.user1_id] || "Unbekannt",
          user2_name: profileMap[row.user2_id] || "Unbekannt",
          created_at: row.created_at,
          hasPair: true,
          hasRegistration: registrationSet.has(key),
          integrityStatus: registrationSet.has(key) ? "ok" : "registration_missing"
        });
      });

      // Zusätzlich akzeptierte Kontaktanfragen anzeigen, wenn daraus noch kein
      // workshop_pair entstanden ist. So bleiben fehlerhafte/unvollständige
      // Datensätze weiterhin sichtbar und prüfbar.
      validRequests.forEach(row => {
        const ids = [row.requester_id, row.recipient_id].map(String).sort();
        const key = `${row.workshop_id}:${ids.join(":")}`;
        if (seen.has(key)) return;
        seen.add(key);
        const hasPair = pairSet.has(key);
        const hasRegistration = registrationSet.has(key);
        let integrityStatus = "pair_missing";
        if (hasPair && hasRegistration) integrityStatus = "ok";
        else if (hasPair && !hasRegistration) integrityStatus = "registration_missing";
        else if (!hasPair && hasRegistration) integrityStatus = "pair_missing_registration_exists";
        combined.push({
          id: row.id,
          workshop_id: row.workshop_id,
          workshop: workshopMap[row.workshop_id] || null,
          user1_id: row.requester_id,
          user2_id: row.recipient_id,
          user1_name: profileMap[row.requester_id] || "Unbekannt",
          user2_name: profileMap[row.recipient_id] || "Unbekannt",
          created_at: row.created_at,
          hasPair,
          hasRegistration,
          integrityStatus
        });
      });

      combined.sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
      setAdminSelfFoundPairs(combined);
    } catch (error) {
      console.error("Selbst gefundene Tanzpaare konnten nicht geladen werden:", error);
      setAdminSelfFoundPairs([]);
    } finally {
      setAdminSelfFoundPairsLoading(false);
    }
  }

  async function loadAdminExternalAssignedCount() {
    setAdminExternalAssignedCountLoading(true);
    try {
      // Der tatsächliche Vermittlungsstatus des externen Tänzers ist
      // workshop_external_availability.status = "assigned".
      // Dadurch zählen stornierte/aufgelöste Vermittlungen nicht weiter.
      const { data, error } = await adminDb
        .from("workshop_external_availability")
        .select("workshop_id,external_dancer_id,workshop_external_dancers!inner(active),workshops!inner(id)")
        .eq("status", "assigned")
        .eq("workshop_external_dancers.active", true);
      if (error) throw error;
      const unique = new Set((data || []).map(row => `${row.workshop_id}:${row.external_dancer_id}`));
      setAdminExternalAssignedCount(unique.size);
    } catch (error) {
      console.error("Externe vermittelte Tanzpaare konnten nicht gezählt werden:", error);
      setAdminExternalAssignedCount(0);
    } finally {
      setAdminExternalAssignedCountLoading(false);
    }
  }

  async function replaceLoginBackground(file) {
    if (readOnly) {
      alert("Dieser Admin-Zugang ist nur zum Lesen freigegeben.");
      return;
    }
    if (!file) return;

    if (!file.type.startsWith("image/")) {
      alert("Bitte wähle eine Bilddatei (JPG oder PNG) aus.");
      return;
    }

    if (file.size > 8 * 1024 * 1024) {
      alert("Das Bild darf maximal 8 MB groß sein.");
      return;
    }

    setBackgroundBusy(true);

    try {
      const { error } = await adminDb.storage
        .from("app-images")
        .upload("login-bg.png", file, {
          upsert: true,
          contentType: file.type,
          cacheControl: "3600"
        });

      if (error) {
        throw new Error(error.message);
      }

      alert(
        "Das Login-Hintergrundbild wurde erfolgreich ersetzt.\n\nBitte die Seite einmal neu laden, damit das neue Bild angezeigt wird."
      );
    } catch (err) {
      console.error("Fehler beim Ersetzen des Login-Hintergrunds:", err);
      alert(
        "Das Hintergrundbild konnte nicht ersetzt werden:\n\n" +
          (err.message || "Unbekannter Fehler") +
          "\n\nFalls ein Storage-/RLS-Fehler erscheint, muss die Admin-Upload-Berechtigung für den Bucket app-images einmal in Supabase eingerichtet werden."
      );
    } finally {
      setBackgroundBusy(false);
    }
  }

