  async function deleteWorkshopHeader() {
    if (readOnly) {
      alert("Dieser Admin-Zugang ist nur zum Lesen freigegeben.");
      return;
    }
    const ok = window.confirm("Das aktuelle Workshop-Titelbild wirklich löschen?\n\nDanach wird wieder das Standardbild verwendet.");
    if (!ok) return;
    setWorkshopHeaderBusy(true);
    try {
      const { data: sessionData, error: sessionError } = await adminDb.auth.getSession();
      if (sessionError) throw sessionError;
      const accessToken = sessionData?.session?.access_token;
      if (!accessToken) throw new Error("Keine gültige Admin-Sitzung gefunden.");
      try { adminDb.storage.setAuth(accessToken); } catch (_) {}

      let { error } = await adminDb.storage.from("app-images").remove(["workshop-header-custom.png"]);
      if (error) {
        const endpoint = `${supabaseUrl}/storage/v1/object/remove/app-images`;
        const response = await fetch(endpoint, {
          method: "POST",
          headers: {
            apikey: supabaseKey,
            Authorization: `Bearer ${accessToken}`,
            "content-type": "application/json"
          },
          body: JSON.stringify({ prefixes: ["workshop-header-custom.png"] })
        });
        if (!response.ok) {
          let detail = "";
          try { detail = await response.text(); } catch (_) {}
          throw new Error(detail || error.message || "Supabase hat das Löschen abgelehnt.");
        }
      }

      try {
        localStorage.setItem(WORKSHOP_HEADER_VERSION_KEY, String(Date.now()));
      } catch (_) {}
      alert("Das Workshop-Titelbild wurde gelöscht. Beim nächsten Laden wird wieder das Standardbild verwendet.");
    } catch (err) {
      console.error("Fehler beim Löschen des Workshop-Titelbildes:", err);
      alert("Das Workshop-Titelbild konnte nicht gelöscht werden:\n" + (err?.message || "Unbekannter Fehler"));
    } finally {
      setWorkshopHeaderBusy(false);
    }
  }

