  async function loadWorkshopRegistrations() {
    setWorkshopRegistrationsLoading(true);

    // Alle Workshops laden, damit der Admin auch einen Workshop ohne
    // bisherige Anmeldung für eine manuelle Paaranmeldung auswählen kann.
    const { data: allWorkshops, error: allWorkshopsError } = await adminDb
      .from("workshops")
      .select("id,title,starts_at,start_time,duration_minutes,recurrence_text,location,cost_per_person,max_pair_count,trainer_name,allow_partner_search,workshop_type")
      .order("starts_at");

    if (allWorkshopsError) {
      setWorkshopRegistrationsLoading(false);
      alert("Fehler beim Laden der Workshops: " + allWorkshopsError.message);
      return;
    }

    setWorkshops(allWorkshops || []);

    const { data, error } = await adminDb
      .from("workshop_registrations")
      .select("id,workshop_id,user1_id,user2_id,user1_name,user1_email,user2_name,user2_email,created_at")
      .order("created_at", { ascending: false });

    if (error) {
      setWorkshopRegistrationsLoading(false);
      alert(
        "Fehler beim Laden der Workshop-Anmeldungen: " +
          error.message
      );
      return;
    }

    const rows = data || [];
    const now = new Date();

    // In "Workshop-Anmeldungen" werden ausschließlich zukünftige,
    // normale Workshops angezeigt. Tanzkreis und Dauerworkshop haben
    // eigene Verwaltungsbereiche. Vergangene Termine werden ausgeblendet.
    const normalFutureWorkshops = (allWorkshops || []).filter(workshop =>
      workshop?.workshop_type !== "tanzkreis" &&
      !workshop?.recurrence_text &&
      !!workshop?.starts_at &&
      new Date(workshop.starts_at) >= now
    );

    const normalWorkshopIds = new Set(
      normalFutureWorkshops.map(workshop => String(workshop.id))
    );

    // Nur echte Anmeldungen zu diesen Workshops übernehmen.
    const normalRows = rows.filter(row =>
      row?.workshop_id &&
      normalWorkshopIds.has(String(row.workshop_id))
    );

    const workshopMap = Object.fromEntries(
      normalFutureWorkshops.map(workshop => [workshop.id, workshop])
    );

    const pairCountByWorkshop = normalRows.reduce((acc, row) => {
      acc[row.workshop_id] = (acc[row.workshop_id] || 0) + 1;
      return acc;
    }, {});

    // Auch Workshops ohne Anmeldung anzeigen, damit der Admin alle
    // zukünftigen Workshops sieht und nicht nur bereits gebuchte.
    const rowsByWorkshop = normalRows.reduce((acc, row) => {
      const key = String(row.workshop_id);
      if (!acc[key]) acc[key] = [];
      acc[key].push(row);
      return acc;
    }, {});

    const displayRows = normalFutureWorkshops.flatMap(workshop => {
      const existing = rowsByWorkshop[String(workshop.id)] || [];
      if (existing.length) {
        return existing.map(row => ({
          ...row,
          workshop,
          registeredPairCount: pairCountByWorkshop[row.workshop_id] || 0,
          isWorkshopPlaceholder: false
        }));
      }

      return [{
        id: null,
        workshop_id: workshop.id,
        user1_id: null,
        user2_id: null,
        user1_name: "",
        user1_email: "",
        user2_name: "",
        user2_email: "",
        created_at: null,
        workshop,
        registeredPairCount: 0,
        isWorkshopPlaceholder: true
      }];
    });

    setWorkshopRegistrations(displayRows);
    setWorkshopRegistrationsLoading(false);
  }

  async function deleteRecurringRegistration(registration) {
    if (readOnly || !registration?.id || deletingRecurringRegistrationId) return;

    const dateText = registration.session_date
      ? new Intl.DateTimeFormat("de-DE", {
          timeZone: "Europe/Berlin",
          weekday: "long",
          day: "2-digit",
          month: "2-digit",
          year: "numeric"
        }).format(new Date(`${registration.session_date}T12:00:00`))
      : "diesen Termin";

    const names = registration.party_size === 2
      ? `${registration.user1_name || "Person 1"} + ${registration.user2_name || "Person 2"}`
      : (registration.user1_name || "Einzelperson");

    if (!window.confirm(
      `Dauerworkshop-Anmeldung wirklich löschen?\\n\\n${dateText}\\n${names}`
    )) return;

    setDeletingRecurringRegistrationId(registration.id);
    try {
      const { data, error } = await adminDb.rpc(
        "admin_cancel_recurring_workshop_registration",
        { p_registration_id: registration.id }
      );
      if (error) throw error;
      if (!data) throw new Error("Die Anmeldung wurde nicht gefunden oder bereits gelöscht.");

      setRecurringRegistrations(prev => prev.filter(r => r.id !== registration.id));
      alert("Die Dauerworkshop-Anmeldung wurde gelöscht. ✅");
    } catch (error) {
      console.error("Dauerworkshop-Anmeldung konnte nicht gelöscht werden:", error);
      alert("Die Anmeldung konnte nicht gelöscht werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setDeletingRecurringRegistrationId("");
    }
  }

  function getNextRecurringRegistrationSummary() {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const upcoming = (recurringRegistrations || [])
      .filter(r => r?.session_date)
      .map(r => ({ ...r, _date: new Date(`${r.session_date}T12:00:00`) }))
      .filter(r => !Number.isNaN(r._date.getTime()) && r._date >= today)
      .sort((a, b) => a._date - b._date);
    if (!upcoming.length) return null;
    const date = upcoming[0].session_date;
    const sameDate = upcoming.filter(r => r.session_date === date);
    const people = sameDate.reduce((sum, r) => sum + Number(r.party_size || 0), 0);
    return { date, registrations: sameDate.length, people, workshopTitle: sameDate[0]?.workshop_title || "Dauerworkshop" };
  }

  function formatRecurringDate(dateString) {
    if (!dateString) return "";
    return new Intl.DateTimeFormat("de-DE", {
      timeZone: "Europe/Berlin", weekday: "short", day: "2-digit", month: "2-digit", year: "numeric"
    }).format(new Date(`${dateString}T12:00:00`));
  }

  function printRecurringRegistrationDate(dateString) {
    const rows = (recurringRegistrations || []).filter(r => r.session_date === dateString);
    if (!rows.length) {
      alert("Für diesen Termin gibt es keine Anmeldungen.");
      return;
    }
    const esc = value => String(value ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\"/g,"&quot;");
    const people = rows.map((r,i) => `<tr><td>${i+1}.</td><td>${esc(r.user1_name || "Ohne Namen")}<br><span>${esc(r.user1_email || "")}</span></td><td>${r.party_size === 2 ? esc(r.user2_name || "Ohne Namen") : "–"}<br><span>${r.party_size === 2 ? esc(r.user2_email || "") : ""}</span></td><td>${r.party_size === 2 ? "Tanzpaar" : "Einzelperson"}</td></tr>`).join("");
    const printWindow = window.open("", "_blank", "width=900,height=700");
    if (!printWindow) { alert("Das Druckfenster konnte nicht geöffnet werden. Bitte Pop-ups erlauben."); return; }
    printWindow.document.write(`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Dauerworkshop – ${esc(formatRecurringDate(dateString))}</title><style>body{font-family:Arial,sans-serif;padding:28px;color:#222}h1{font-size:24px;margin:0 0 8px}p{color:#555}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #ccc;padding:8px;text-align:left;vertical-align:top}th{background:#f3f0f8}span{color:#666;font-size:11px}</style></head><body><h1>📅 Dauerworkshop – ${esc(formatRecurringDate(dateString))}</h1><p>${esc(rows[0]?.workshop_title || "Dauerworkshop")} · ${rows.length} Anmeldungen · ${rows.reduce((sum,r)=>sum+Number(r.party_size||0),0)} Personen</p><table><thead><tr><th>Nr.</th><th>Person 1</th><th>Person 2</th><th>Art</th></tr></thead><tbody>${people}</tbody></table></body></html>`);
    printWindow.document.close(); printWindow.focus(); setTimeout(() => printWindow.print(), 250);
  }

  async function shareRecurringRegistrationDatePdf(dateString) {
    const rows = (recurringRegistrations || []).filter(r => r.session_date === dateString);
    if (!rows.length) { alert("Für diesen Termin gibt es keine Anmeldungen."); return; }
    const safe = value => String(value ?? "").replace(/[\r\n]+/g," ").replace(/[–—]/g,"-").replace(/[^\x00-\xFF]/g,"?");
    const escPdf = value => safe(value).replace(/\\/g,"\\\\").replace(/\(/g,"\\(").replace(/\)/g,"\\)");
    const PAGE_W=595, PAGE_H=842, LEFT=45, RIGHT=550, ROW_H=24, TOP=790, BOTTOM=48;
    const cmds=[]; let y=TOP;
    const text=(x,yy,v,size=13,bold=false)=>cmds.push(`BT /${bold?"F2":"F1"} ${size} Tf 1 0 0 1 ${x} ${yy} Tm (${escPdf(v)}) Tj ET`);
    const line=(x1,y1,x2,y2)=>cmds.push(`0.7 w ${x1} ${y1} m ${x2} ${y2} l S`);
    const rect=(x,yy,w,h,fill=false)=>{ if(fill) cmds.push(`0.95 0.94 0.97 rg ${x} ${yy} ${w} ${h} re f 0 0 0 rg`); cmds.push(`0.7 w ${x} ${yy} ${w} ${h} re S`); };
    const cols=[LEFT,85,300,455,RIGHT];
    const header=()=>{const b=y-ROW_H;rect(LEFT,b,RIGHT-LEFT,ROW_H,true);for(let i=1;i<cols.length-1;i++)line(cols[i],b,cols[i],y);["Nr.","Person 1","Person 2","Art"].forEach((v,i)=>text(cols[i]+7,b+7,v,12,true));y=b;};
    text(LEFT,y,"Dauerworkshop - Teilnehmerliste",20,true); y-=28;
    text(LEFT,y,`${safe(rows[0]?.workshop_title || "Dauerworkshop")} - ${safe(formatRecurringDate(dateString))}`,14,true); y-=20;
    text(LEFT,y,`${rows.length} Anmeldungen - ${rows.reduce((sum,r)=>sum+Number(r.party_size||0),0)} Personen`,13,false); y-=25; header();
    rows.forEach((r,i)=>{if(y-ROW_H<BOTTOM){return;} const b=y-ROW_H;rect(LEFT,b,RIGHT-LEFT,ROW_H);for(let j=1;j<cols.length-1;j++)line(cols[j],b,cols[j],y);text(cols[0]+7,b+7,`${i+1}.`,12);text(cols[1]+7,b+7,safe(r.user1_name||"Ohne Namen").slice(0,32),12);text(cols[2]+7,b+7,r.party_size===2?safe(r.user2_name||"Ohne Namen").slice(0,28):"-",12);text(cols[3]+7,b+7,r.party_size===2?"Tanzpaar":"Einzel",12);y=b;});
    const objects=["<< /Type /Catalog /Pages 2 0 R >>"]; const kids=[]; const pageObj=3, contentObj=4; kids.push(`${pageObj} 0 R`); objects.push(`<< /Type /Pages /Kids [${kids.join(" ")}] /Count 1 >>`); const content=cmds.join("\n"); objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> /Contents ${contentObj} 0 R >>`); objects.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`); objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"); objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"); let pdf="%PDF-1.4\n%\xE2\xE3\xCF\xD3\n", offsets=[0]; objects.forEach((obj,i)=>{offsets[i+1]=pdf.length;pdf+=`${i+1} 0 obj\n${obj}\nendobj\n`;}); const xref=pdf.length; pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`; for(let i=1;i<=objects.length;i++)pdf+=`${String(offsets[i]).padStart(10,"0")} 00000 n \n`; pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`; const bytes=new Uint8Array(pdf.length);for(let i=0;i<pdf.length;i++)bytes[i]=pdf.charCodeAt(i)&255; const blob=new Blob([bytes],{type:"application/pdf"}); const file=new File([blob],`Dauerworkshop-${dateString}.pdf`,{type:"application/pdf"});
    try { if(navigator.share && (!navigator.canShare || navigator.canShare({files:[file]}))){await navigator.share({title:"Dauerworkshop Teilnehmerliste",text:`Teilnehmerliste ${formatRecurringDate(dateString)}`,files:[file]});return;} } catch(e){if(e?.name==="AbortError")return;}
    const url=URL.createObjectURL(blob), a=document.createElement("a"); a.href=url; a.download=file.name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),2000);
  }

  async function loadRecurringRegistrations() {
    setRecurringRegistrationsLoading(true);
    try {
      const { data, error } = await adminDb.rpc("admin_get_recurring_workshop_registrations");
      if (error) throw error;
      setRecurringRegistrations(data || []);
    } catch (error) {
      console.error("Dauerworkshop-Anmeldungen konnten nicht geladen werden:", error);
      setRecurringRegistrations([]);
    } finally {
      setRecurringRegistrationsLoading(false);
    }
  }

  async function loadMatchSeekers(workshopId) {
    if (!workshopId) {
      setMatchSeekers([]);
      return;
    }

    setMatchSeekersLoading(true);
    try {
      const { data, error } = await adminDb.rpc("admin_get_workshop_seekers", {
        p_workshop_id: Number(workshopId)
      });
      if (error) throw error;
      setMatchSeekers(data || []);
      setMatchForm(prev => ({
        ...prev,
        seekerUserId: (data || []).some(x => x.user_id === prev.seekerUserId)
          ? prev.seekerUserId
          : ""
      }));
    } catch (error) {
      console.error("Suchende für Vermittlung konnten nicht geladen werden:", error);
      setMatchSeekers([]);
      alert("Die Suchenden konnten nicht geladen werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setMatchSeekersLoading(false);
    }
  }

  async function matchWorkshopSeekerWithGuest() {
    if (readOnly || matchBusy) return;

    const workshopId = Number(matchForm.workshopId);
    const seekerUserId = matchForm.seekerUserId;
    const partnerName = matchForm.partnerName.trim();
    const partnerEmail = matchForm.partnerEmail.trim();

    const seeker = matchSeekers.find(x => x.user_id === seekerUserId);

    if (!workshopId || !seekerUserId || !seeker || !partnerName) {
      alert("Bitte Workshop, eine suchende Person und den Namen des Tanzpartners auswählen bzw. angeben.");
      return;
    }

    if (!window.confirm(
      `${seeker.display_name || "Die suchende Person"} mit „${partnerName}“ für diesen Workshop zusammenführen?\n\n` +
      `Die aktive Tanzpartnersuche wird dabei beendet und eine Workshop-Paaranmeldung angelegt.`
    )) return;

    setMatchBusy(true);
    try {
      const { data: registrationId, error } = await adminDb.rpc("admin_match_workshop_seeker_guest", {
        p_workshop_id: workshopId,
        p_seeker_user_id: seekerUserId,
        p_partner_name: partnerName,
        p_partner_email: partnerEmail || null
      });

      if (error) throw error;

      const workshop = workshops.find(w => Number(w.id) === workshopId);
      const seekerEmail = seeker.email || "";
      let mailWarning = "";

      if (!trainingModeActive && (seekerEmail || partnerEmail)) {
        const mailResult = await sendWorkshopPairConfirmation({
          workshopId,
          registrationId,
          user1Name: seeker.display_name || "Tanzpartner-Suchende Person",
          user1Email: seekerEmail,
          user2Name: partnerName,
          user2Email: partnerEmail,
          costPerPerson: workshop?.cost_per_person ?? null
        });
        if (!mailResult.ok) {
          mailWarning = "\n\n⚠️ Die Paaranmeldung wurde gespeichert, aber die Bestätigungs-Mail konnte nicht vollständig versendet werden.";
        }
      }

      setMatchSeekers(prev => prev.filter(x => x.user_id !== seekerUserId));
      setMatchForm({
        workshopId: String(workshopId),
        seekerUserId: "",
        partnerName: "",
        partnerEmail: ""
      });

      await Promise.all([loadWorkshopRegistrations(), loadRecurringSeekers()]);
      alert(
        `🤝 ${seeker.display_name || "Die Person"} wurde erfolgreich mit „${partnerName}“ zusammengeführt.` +
        mailWarning
      );
    } catch (error) {
      console.error("Tanzpartnervermittlung fehlgeschlagen:", error);
      alert("Die Vermittlung konnte nicht gespeichert werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setMatchBusy(false);
    }
  }

  async function reviewAutomaticMatchProposal(proposalId, approve) {
    if (readOnly || automaticMatchReviewBusy) return;
    setAutomaticMatchReviewBusy(String(proposalId));
    try {
      if (trainingModeActive) {
        alert(`🧪 ${approve ? "Freigabe" : "Ablehnung"} ausprobiert.\n\nIm Demo-Modus wird nichts gespeichert.`);
        return;
      }
      const { data, error } = await adminDb.rpc("admin_review_workshop_match_proposal", {
        p_proposal_id: proposalId,
        p_approve: !!approve
      });
      if (error) throw error;
      await loadAdminMatchProposals(registeredMatchWorkshopId || null);
      alert(approve
        ? "🤝 Vorschlag freigegeben. Beide Personen erhalten jetzt den Vermittlungsvorschlag."
        : "Vorschlag abgelehnt.");
      return data;
    } catch (error) {
      console.error("Automatischer Vermittlungsvorschlag konnte nicht geprüft werden:", error);
      alert("Der Vorschlag konnte nicht geprüft werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setAutomaticMatchReviewBusy("");
    }
  }

  async function loadAdminMatchProposals(workshopId = null) {
    setAdminMatchProposalsLoading(true);
    try {
      const [{ data, error }, { data: externalData, error: externalError }] = await Promise.all([
        adminDb.rpc("admin_get_workshop_match_proposals", {
          p_workshop_id: workshopId ? Number(workshopId) : null
        }),
        adminDb.rpc("admin_get_external_match_proposals", {
          p_workshop_id: workshopId ? Number(workshopId) : null
        })
      ]);
      if (error) throw error;
      if (externalError) throw externalError;
      const proposals = data || [];
      setAdminMatchProposals(proposals);
      setAutomaticMatchPendingCount(proposals.filter(p => p.status === "admin_review").length);
      setAdminExternalMatchProposals(externalData || []);
    } catch (error) {
      console.error("Vermittlungsvorschläge konnten nicht geladen werden:", error);
      setAdminMatchProposals([]);
    } finally {
      setAdminMatchProposalsLoading(false);
    }
  }


  // Chatstatus für Vermittlungen: nur echte Nachrichten zwischen den beiden
  // Tänzern zählen. Nachrichten von Peter & Bettina sind reine Informationen
  // und gelten niemals als persönlicher Chatkontakt.
  async function loadMediationChatStatuses(proposals = adminMatchProposals, externalProposals = adminExternalMatchProposals) {
    try {
      const rows = [
        ...(proposals || []).map(p => ({
          key: `proposal:${p.id}`,
          workshopId: p.workshop_id,
          user1Id: p.user1_id,
          user2Id: p.user2_id
        })),
        ...(externalProposals || []).map(p => ({
          key: `external:${p.id}`,
          workshopId: p.workshop_id,
          user1Id: p.seeker_user_id || p.user_id || p.seeker_id,
          user2Id: null
        })),
        ...(contactRequests || []).filter(r => r.status === "pending" && r.workshop_id).map(r => ({
          key: `contact:${r.id}`,
          workshopId: r.workshop_id,
          user1Id: r.requester_id,
          user2Id: r.recipient_id
        }))
      ].filter(r => r.workshopId && r.user1Id);

      const workshopIds = [...new Set(rows.map(r => r.workshopId).filter(Boolean))];
      if (!workshopIds.length) {
        setMediationChatStatus({});
        return;
      }

      const { data, error } = await adminDb
        .from("messages")
        .select("id,sender_id,recipient_id,workshop_id,created_at")
        .in("workshop_id", workshopIds)
        .neq("sender_id", ADMIN_USER_ID)
        .neq("recipient_id", ADMIN_USER_ID)
        .order("created_at", { ascending: true })
        .limit(5000);

      if (error) throw error;

      const next = {};
      for (const row of rows) {
        const messages = (data || []).filter(m => {
          if (String(m.workshop_id) !== String(row.workshopId)) return false;
          if (!row.user2Id) {
            return String(m.sender_id) === String(row.user1Id) ||
              String(m.recipient_id) === String(row.user1Id);
          }
          const pair = new Set([String(row.user1Id), String(row.user2Id)]);
          return pair.has(String(m.sender_id)) && pair.has(String(m.recipient_id));
        });

        const writers = new Set();
        messages.forEach(m => writers.add(String(m.sender_id)));

        if (writers.size >= 2) {
          next[row.key] = "Beide haben geschrieben";
        } else if (writers.size === 1) {
          const writerId = [...writers][0];
          const writer = String(row.user1Id) === writerId ? "Person 1" : "Person 2";
          next[row.key] = `${writer} hat geschrieben · Antwort steht aus`;
        } else {
          next[row.key] = "Noch kein persönlicher Chatkontakt";
        }
      }
      setMediationChatStatus(next);
    } catch (error) {
      console.warn("Chatstatus der Vermittlungen konnte nicht geladen werden:", error);
      setMediationChatStatus({});
    }
  }

  // Eine Vermittlung wird getrennt, ohne Nutzer oder Workshop-Anmeldung zu löschen.
  // Wichtig: Es wird bewusst KEIN updated_at auf workshop_match_proposals
  // geschrieben, weil diese Tabelle in älteren Projekten keine solche Spalte hat.
  async function separateMediation(item) {
    if (readOnly || separatingMediationKey) return;
    const key = item?.key || `${item?.workshopId}:${item?.user1Id}:${item?.user2Id}`;
    const workshopTitle = item?.workshopTitle || "diesem Workshop";
    const name1 = item?.user1Name || "Person 1";
    const name2 = item?.user2Name || "Person 2";

    if (!window.confirm(
      `Vermittlung ${name1} ↔ ${name2} für „${workshopTitle}“ wirklich trennen?\n\n` +
      `Die Workshop-Anmeldung bleibt bestehen. Nur die Tanzpartnerschaft/Vermittlung wird gelöst.`
    )) return;

    setSeparatingMediationKey(key);
    try {
      // 1. Tatsächliche Tanzpartnerschaft entfernen – workshop_pairs hat
      // bewusst KEINE id-Spalte. Deshalb immer über Workshop + beide User löschen.
      // Die workshop_registrations-Zeile bleibt ausdrücklich unangetastet.
      if (item.user1Id && item.user2Id && item.workshopId) {
        const ids = [String(item.user1Id), String(item.user2Id)];
        const { data: pairs, error: pairFindError } = await adminDb
          .from("workshop_pairs")
          .select("workshop_id,user1_id,user2_id")
          .eq("workshop_id", item.workshopId);
        if (pairFindError) throw pairFindError;

        const match = (pairs || []).find(p => {
          const pids = [String(p.user1_id), String(p.user2_id)];
          return pids.includes(ids[0]) && pids.includes(ids[1]);
        });
        if (match) {
          const { error } = await adminDb
            .from("workshop_pairs")
            .delete()
            .eq("workshop_id", item.workshopId)
            .eq("user1_id", match.user1_id)
            .eq("user2_id", match.user2_id);
          if (error) throw error;
        }
      }

      // 2. Offene/angenommene Kontaktanfrage beenden, damit die alte
      // Vermittlung nicht sofort wieder als aktiv erscheint.
      if (item.user1Id && item.user2Id && item.workshopId) {
        const { data: contacts, error: contactFindError } = await adminDb
          .from("contact_requests")
          .select("id,requester_id,recipient_id,status")
          .eq("workshop_id", item.workshopId);
        if (contactFindError) throw contactFindError;

        const contact = (contacts || []).find(c => {
          const ids = [String(c.requester_id), String(c.recipient_id)];
          return ids.includes(String(item.user1Id)) && ids.includes(String(item.user2Id));
        });
        if (contact?.id && ["pending", "accepted"].includes(contact.status)) {
          const { error } = await adminDb
            .from("contact_requests")
            .update({ status: "cancelled" })
            .eq("id", contact.id);
          if (error) throw error;
        }
      }

      // 3. Einen zugehörigen offenen/abgeschlossenen Vorschlag entfernen.
      // Kein updated_at verwenden.
      if (item.proposalId) {
        const { error } = await adminDb
          .from("workshop_match_proposals")
          .delete()
          .eq("id", item.proposalId);
        if (error && !/permission|policy|not found/i.test(error.message || "")) throw error;
      }

      await Promise.all([
        loadAdminSelfFoundPairs(),
        loadAdminMatchProposals(null),
        loadContactRequests()
      ]);
      alert(`✅ Die Vermittlung ${name1} ↔ ${name2} wurde getrennt.\n\nDie Workshop-Anmeldung und die Nutzer bleiben erhalten.`);
    } catch (error) {
      console.error("Vermittlung konnte nicht getrennt werden:", error);
      alert("❌ Die Vermittlung konnte nicht getrennt werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setSeparatingMediationKey("");
    }
  }

  useEffect(() => {
    if (view !== "matching") return;
    loadMediationChatStatuses();
  }, [view, adminMatchProposals, adminExternalMatchProposals, contactRequests]);

  async function loadRegisteredMatchSeekers(workshopId) {
    if (!workshopId) {
      setRegisteredMatchSeekers([]);
      setRegisteredMatchUser1Id("");
      setRegisteredMatchUser2Id("");
      return;
    }

    setRegisteredMatchSeekersLoading(true);
    try {
      const [{ data: seekers, error: seekerError }, { data: registrations, error: registrationError }, { data: pairs, error: pairError }] =
        await Promise.all([
          adminDb.rpc("admin_get_workshop_seekers", { p_workshop_id: Number(workshopId) }),
          adminDb.from("workshop_registrations").select("user1_id,user2_id").eq("workshop_id", Number(workshopId)),
          adminDb.from("workshop_pairs").select("user1_id,user2_id").eq("workshop_id", Number(workshopId))
        ]);

      if (seekerError) throw seekerError;
      if (registrationError) throw registrationError;
      if (pairError) throw pairError;

      const registeredIds = new Set(
        (registrations || []).flatMap(r => [r.user1_id, r.user2_id]).filter(Boolean).map(String)
      );
      const pairedIds = new Set(
        (pairs || []).flatMap(r => [r.user1_id, r.user2_id]).filter(Boolean).map(String)
      );

      const openSeekers = (seekers || []).filter(person => {
        const id = String(person.user_id);
        return !registeredIds.has(id) && !pairedIds.has(id);
      });

      setRegisteredMatchSeekers(openSeekers);
      setRegisteredMatchUser1Id(prev => openSeekers.some(x => String(x.user_id) === String(prev)) ? prev : "");
      setRegisteredMatchUser2Id(prev => openSeekers.some(x => String(x.user_id) === String(prev)) ? prev : "");
    } catch (error) {
      console.error("Offene Tanzpartnersuchen konnten nicht geladen werden:", error);
      setRegisteredMatchSeekers([]);
      setRegisteredMatchUser1Id("");
      setRegisteredMatchUser2Id("");
      alert("Die offenen Tanzpartnersuchen konnten nicht geladen werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setRegisteredMatchSeekersLoading(false);
    }
  }

  async function mediateRegisteredSeekers() {
    if (readOnly || registeredMatchBusy) return;

    const workshopId = Number(registeredMatchWorkshopId);
    const user1 = registeredMatchSeekers.find(x => String(x.user_id) === String(registeredMatchUser1Id));
    const user2 = registeredMatchSeekers.find(x => String(x.user_id) === String(registeredMatchUser2Id));

    if (!workshopId || !user1 || !user2 || String(user1.user_id) === String(user2.user_id)) {
      alert("Bitte Workshop und zwei unterschiedliche offene Tanzpartnersuchende auswählen.");
      return;
    }

    const workshop = workshops.find(w => Number(w.id) === workshopId);
    const name1 = user1.display_name || "Tanzpartner-Suchende Person";
    const name2 = user2.display_name || "Tanzpartner-Suchende Person";

    if (!window.confirm(
      `${name1} und ${name2} für „${workshop?.title || "diesen Workshop"}“ vorschlagen?\n\n` +
      `Beide Personen erhalten einen Vermittlungsvorschlag. Erst wenn BEIDE annehmen, wird die Tanzpartnerschaft und die Workshop-Anmeldung angelegt.`
    )) return;

    setRegisteredMatchBusy(true);
    try {
      if (trainingModeActive) {
        alert(`🧪 Vermittlung ausprobiert.\n\n${name1} und ${name2} würden beide einen Vorschlag erhalten. Es wurde nichts gespeichert.`);
        return;
      }

      const { data: proposalId, error } = await adminDb.rpc("admin_create_workshop_match_proposal", {
        p_workshop_id: workshopId,
        p_user1_id: user1.user_id,
        p_user2_id: user2.user_id
      });
      if (error) throw error;

      setRegisteredMatchUser1Id("");
      setRegisteredMatchUser2Id("");
      await Promise.all([
        loadRegisteredMatchSeekers(workshopId),
        loadAdminMatchProposals(workshopId)
      ]);

      alert(`🤝 Vermittlungsvorschlag gesendet.\n\n${name1} und ${name2} müssen jetzt jeweils selbst annehmen.`);
      return proposalId;
    } catch (error) {
      console.error("Vermittlungsvorschlag konnte nicht erstellt werden:", error);
      alert("Der Vermittlungsvorschlag konnte nicht erstellt werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setRegisteredMatchBusy(false);
    }
  }

  async function loadExternalDancers() {
    setExternalDancersLoading(true);
    setExternalAvailabilityLoading(true);
    try {
      const [{ data: dancers, error: dancerError }, { data: availability, error: availabilityError }] =
        await Promise.all([
          adminDb.rpc("admin_get_external_dancers"),
          adminDb.rpc("admin_get_external_availability")
        ]);

      if (dancerError) throw dancerError;
      if (availabilityError) throw availabilityError;

      setExternalDancers(dancers || []);
      setExternalAvailability(availability || []);
    } catch (error) {
      console.error("Externe Tänzer konnten nicht geladen werden:", error);
      setExternalDancers([]);
      setExternalAvailability([]);
      alert("Die externen Tänzer konnten nicht geladen werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setExternalDancersLoading(false);
      setExternalAvailabilityLoading(false);
    }
  }

  async function saveExternalDancer() {
    if (readOnly || externalDancerBusy) return;
    const name = externalDancerForm.name.trim();
    if (!name) {
      alert("Bitte einen Namen angeben.");
      return;
    }

    setExternalDancerBusy(true);
    try {
      if (trainingModeActive) {
        alert(`🧪 Externen Tänzer speichern ausprobiert.\n\n${name}\nEs wurde nichts gespeichert.`);
        return;
      }

      const { data: id, error } = await adminDb.rpc("admin_save_external_dancer", {
        p_id: externalDancerForm.id || null,
        p_name: name,
        p_email: externalDancerForm.email.trim() || null,
        p_phone: externalDancerForm.phone.trim() || null,
        p_notes: externalDancerForm.notes.trim() || null
      });
      if (error) throw error;

      setExternalDancerForm({ id: "", name: "", email: "", phone: "", notes: "" });
      await loadExternalDancers();
      alert(externalDancerForm.id ? "Externer Tänzer wurde aktualisiert. ✅" : "Externer Tänzer wurde vorgemerkt. ✅");
    } catch (error) {
      console.error("Externer Tänzer konnte nicht gespeichert werden:", error);
      alert("Der externe Tänzer konnte nicht gespeichert werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setExternalDancerBusy(false);
    }
  }

  async function deactivateExternalDancer(id, name) {
    if (readOnly || !id) return;
    if (!window.confirm(`„${name || "Dieser externe Tänzer"}“ wirklich aus dem verfügbaren Pool entfernen?`)) return;

    if (trainingModeActive) {
      alert("🧪 Entfernen ausprobiert. Im Demo-Modus wird nichts gespeichert.");
      return;
    }

    try {
      const { data, error } = await adminDb.rpc("admin_deactivate_external_dancer", { p_id: id });
      if (error) throw error;
      if (!data) throw new Error("Der externe Tänzer wurde nicht gefunden.");
      await loadExternalDancers();
      alert("Externer Tänzer wurde aus dem Pool entfernt. ✅");
    } catch (error) {
      console.error("Externer Tänzer konnte nicht entfernt werden:", error);
      alert("Der externe Tänzer konnte nicht entfernt werden: " + (error?.message || "Unbekannter Fehler"));
    }
  }

  function getExternalEligibleWorkshops() {
    return (workshops || [])
      .filter(w => w.allow_partner_search !== false)
      .filter(w => !w.starts_at || new Date(w.starts_at) >= new Date())
      .sort((a, b) => {
        const da = a.starts_at ? new Date(a.starts_at).getTime() : Number.MAX_SAFE_INTEGER;
        const db = b.starts_at ? new Date(b.starts_at).getTime() : Number.MAX_SAFE_INTEGER;
        return da - db;
      });
  }

  function externalWorkshopDateTime(w) {
    const date = w.starts_at ? formatDate(w.starts_at) : (w.recurrence_text || "Termin offen");
    const time = w.start_time ? String(w.start_time).slice(0, 5) : (w.starts_at ? formatTime(w.starts_at) : "");
    return `${date}${time ? ` · ${time} Uhr` : ""}`;
  }

  function openExternalPrintWindow(title, bodyHtml, css) {
    // Druckdialog direkt aus der Benutzeraktion öffnen. Android/Chrome kann
    // window.print() blockieren, wenn es erst nach einem setTimeout ausgeführt wird.
    // Deshalb wird hier kein verzögertes print() verwendet.
    const frame = document.createElement("iframe");
    frame.style.position = "fixed";
    frame.style.left = "-10000px";
    frame.style.top = "0";
    frame.style.width = "794px";
    frame.style.height = "1123px";
    frame.style.border = "0";
    frame.style.background = "white";
    frame.setAttribute("aria-hidden", "true");
    document.body.appendChild(frame);

    const doc = frame.contentDocument || frame.contentWindow?.document;
    if (!doc || !frame.contentWindow) {
      frame.remove();
      alert("Die Druckansicht konnte nicht erstellt werden.");
      return;
    }

    doc.open();
    doc.write(`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>${esc(title)}</title><style>${css}</style></head><body>${bodyHtml}</body></html>`);
    doc.close();

    // Wichtig: print() unmittelbar aus dem Klick-Handler heraus aufrufen.
    // Kein setTimeout / kein onload, damit Chrome die Benutzeraktion erkennt.
    try {
      frame.contentWindow.focus();
      frame.contentWindow.print();
    } catch (err) {
      frame.remove();
      alert("Der Druckdialog konnte nicht geöffnet werden. Bitte erneut auf Drucken tippen.");
      return;
    }

    // Das iframe erst nach dem Druckversuch entfernen. Bei manchen Browsern
    // wird der Dialog synchron geöffnet, bei anderen kurz danach.
    setTimeout(() => {
      if (document.body.contains(frame)) frame.remove();
    }, 3000);
  }

  function createExternalDancerPdfBlob(blankList = false) {
    if (!externalDancers.length) return null;

    const safe = value => String(value ?? "")
      .replace(/[\r\n]+/g, " ")
      .replace(/[“”„‟]/g, '"')
      .replace(/[‘’‚‛]/g, "'")
      .replace(/[–—]/g, "-")
      .replace(/…/g, "...")
      .replace(/·/g, "-")
      .replace(/[^\x00-\xFF]/g, "?");
    const escPdf = value => safe(value)
      .replace(/\\/g, "\\\\")
      .replace(/\(/g, "\\(")
      .replace(/\)/g, "\\)");

    const PAGE_W = 595, PAGE_H = 842, LEFT = 42, RIGHT = 553, TOP = 795, BOTTOM = 42;
    const pages = [];
    let commands = [];
    let y = TOP;

    const newPage = () => {
      if (commands.length) pages.push(commands);
      commands = [];
      y = TOP;
    };
    const ensure = h => { if (y - h < BOTTOM) newPage(); };
    const drawText = (x, yy, value, size = 14, bold = false) => {
      commands.push(`BT /${bold ? "F2" : "F1"} ${size} Tf 1 0 0 1 ${x} ${yy} Tm (${escPdf(value)}) Tj ET`);
    };
    const line = (x1, y1, x2, y2) => commands.push(`0.7 w ${x1} ${y1} m ${x2} ${y2} l S`);
    const wrap = (value, maxChars = 70) => {
      const words = safe(value).split(/\s+/).filter(Boolean);
      const lines = [];
      let current = "";
      words.forEach(word => {
        const next = current ? `${current} ${word}` : word;
        if (next.length > maxChars && current) { lines.push(current); current = word; }
        else current = next;
      });
      if (current) lines.push(current);
      return lines.length ? lines : [""];
    };

    drawText(LEFT, y, blankList ? "Blankoliste - externe Taenzer" : "Externe Taenzer - Verfuegbarkeiten", 20, true);
    y -= 28;
    drawText(LEFT, y, blankList
      ? "Alle zukuenftigen Workshops mit aktivierter Tanzpartnersuche"
      : "Vorgemerkte Taenzer mit ihren vorgemerkten Workshop-Terminen", 14);
    y -= 26;
    line(LEFT, y, RIGHT, y);
    y -= 18;

    const eligible = getExternalEligibleWorkshops();
    externalDancers.forEach((dancer, dancerIndex) => {
      const available = blankList
        ? eligible
        : eligible.filter(w => externalAvailability.some(a =>
            String(a.external_dancer_id) === String(dancer.id) &&
            Number(a.workshop_id) === Number(w.id) &&
            (a.status === "available" || a.status === "assigned")
          ));

      ensure(75);
      drawText(LEFT, y, `${dancerIndex + 1}. ${safe(dancer.name || "Externer Taenzer")}`, 16, true);
      y -= 19;
      const contact = [dancer.phone ? `Telefon: ${dancer.phone}` : "", dancer.email ? `E-Mail: ${dancer.email}` : ""].filter(Boolean).join("   ");
      if (contact) { drawText(LEFT + 10, y, contact, 14); y -= 18; }
      if (dancer.notes) { drawText(LEFT + 10, y, `Bemerkung: ${safe(dancer.notes)}`, 14); y -= 18; }

      if (!available.length) {
        ensure(28);
        drawText(LEFT + 10, y, blankList ? "Keine zukuenftigen Workshops vorhanden." : "Keine vorgemerkten Workshop-Termine.", 14);
        y -= 20;
      } else {
        available.forEach(w => {
          const date = w.starts_at ? formatDate(w.starts_at) : (w.recurrence_text || "Termin offen");
          const time = w.start_time ? String(w.start_time).slice(0, 5) : (w.starts_at ? formatTime(w.starts_at) : "");
          const title = safe(w.title || "Workshop");
          const status = externalAvailability.find(a =>
            String(a.external_dancer_id) === String(dancer.id) && Number(a.workshop_id) === Number(w.id)
          )?.status === "assigned" ? " - vermittelt" : "";
          const rowLines = wrap(`${date}${time ? ` - ${time} Uhr` : ""} - ${title}${w.level ? ` - ${w.level}` : ""}${status}`, 72);
          ensure(20 * rowLines.length + 5);
          rowLines.forEach((row, idx) => { drawText(LEFT + 10, y, `${idx === 0 ? "- " : "  "}${row}`, 14); y -= 18; });
        });
      }
      y -= 6;
      line(LEFT, y, RIGHT, y);
      y -= 16;
    });

    if (commands.length) pages.push(commands);

    const objects = [];
    const pageIds = [];
    const contentIds = [];
    objects.push("<< /Type /Catalog /Pages 2 0 R >>");
    objects.push("");
    pages.forEach(cmds => {
      const stream = cmds.join("\n");
      contentIds.push(objects.length + 1);
      objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);
      pageIds.push(objects.length + 1);
      objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] /Resources << /Font << /F1 0 0 R /F2 0 0 R >> >> /Contents ${contentIds[contentIds.length - 1]} 0 R >>`);
    });
    const font1Id = objects.length + 1;
    objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
    const font2Id = objects.length + 1;
    objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
    pages.forEach((_, index) => {
      const objIndex = pageIds[index] - 1;
      objects[objIndex] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] /Resources << /Font << /F1 ${font1Id} 0 R /F2 ${font2Id} 0 R >> >> /Contents ${contentIds[index]} 0 R >>`;
    });
    objects[1] = `<< /Type /Pages /Kids [${pageIds.map(id => `${id} 0 R`).join(" ")}] /Count ${pageIds.length} >>`;

    let pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";
    const offsets = [0];
    objects.forEach((obj, index) => {
      offsets[index + 1] = pdf.length;
      pdf += `${index + 1} 0 obj\n${obj}\nendobj\n`;
    });
    const xrefOffset = pdf.length;
    pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
    for (let i = 1; i <= objects.length; i++) pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
    pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;

    const bytes = new Uint8Array(pdf.length);
    for (let i = 0; i < pdf.length; i++) bytes[i] = pdf.charCodeAt(i) & 0xFF;
    return new Blob([bytes], { type: "application/pdf" });
  }

  async function createAndShareExternalDancerPdf() {
    const blob = createExternalDancerPdfBlob(false);
    if (!blob) { alert("Es sind noch keine externen Tänzer vorgemerkt."); return; }
    const file = new File([blob], "Externe-Taenzer-Verfuegbarkeiten.pdf", { type: "application/pdf" });
    try {
      if (navigator.share && (!navigator.canShare || navigator.canShare({ files: [file] }))) {
        await navigator.share({ title: "Externe Tänzer", text: "Externe Tänzer mit Workshop-Terminen", files: [file] });
        return;
      }
    } catch (error) {
      if (error?.name === "AbortError") return;
    }
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = file.name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  }

