    if (!externalDancers.length) {
      alert("Es sind noch keine externen Tänzer vorgemerkt.");
      return;
    }
    const eligible = getExternalEligibleWorkshops();
    const dancerBlocks = externalDancers.map(dancer => {
      const available = eligible.filter(w => externalAvailability.some(a =>
        String(a.external_dancer_id) === String(dancer.id) &&
        Number(a.workshop_id) === Number(w.id) &&
        (a.status === "available" || a.status === "assigned")
      ));
      const rows = available.length ? available.map(w => `<tr><td>${esc(externalWorkshopDateTime(w))}</td><td><strong>${esc(w.title || "Workshop")}</strong></td><td>${w.level ? esc(w.level) : ""}</td></tr>`).join("") : `<tr><td colspan="3" class="empty">Keine Workshop-Termine vorgemerkt.</td></tr>`;
      return `<section class="dancer"><h2>${esc(dancer.name || "Externer Tänzer")}</h2><div class="data">${dancer.phone ? `📞 ${esc(dancer.phone)}<br>` : ""}${dancer.email ? `✉️ ${esc(dancer.email)}<br>` : ""}${dancer.notes ? `📝 ${esc(dancer.notes)}` : ""}</div><h3>Verfügbare Workshops</h3><table><thead><tr><th>Datum / Uhrzeit</th><th>Workshop</th><th>Level</th></tr></thead><tbody>${rows}</tbody></table></section>`;
    }).join("");
    openExternalPrintWindow(
      "Externe Tänzer – Verfügbarkeiten",
      `<h1>👥 Externe Tänzer – Verfügbarkeiten</h1><p>Ausdruck der aktuell vorgemerkten externen Tänzer mit den Workshops, für die sie verfügbar sind.</p>${dancerBlocks}`,
      `body{font-family:Arial,sans-serif;padding:28px;color:#222}h1{margin:0 0 8px}p{color:#666}.dancer{border:1px solid #ccc;border-radius:10px;padding:16px;margin:0 0 18px;break-inside:avoid}.data{line-height:1.6;margin:8px 0 14px}h3{margin:12px 0 7px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:7px;text-align:left;vertical-align:top}th{background:#f3f0f8}.empty{color:#777;font-style:italic}@media print{body{padding:10px}}`
    );
