              { icon: "👁️", value: adminVisitStatsLoading ? "…" : adminVisitStats.total, label: "Seitenaufrufe", color: "#b45309", bg: "#fff9ed", border: "#f2e3bf", sub: adminVisitStatsLoading ? "…" : `Heute: ${adminVisitStats.today}` }
