                            const date = workshop?.starts_at ? formatDate(workshop.starts_at) : "Termin offen";
                            const time = workshop?.start_time ? String(workshop.start_time).slice(0, 5) : (workshop?.starts_at ? formatTime(workshop.starts_at) : "");
                            const status = pair.integrityStatus;
                            const ok = status === "ok";
